local function dungeonKey(step)
    if not step then return end
    local rule = step.EnterInstance or step.LeaveInstance or step.KillNPC
    return step.Dungeon or (rule and rule.dungeonKey)
end--[[APR_DIAG]]; dungeonKey = APRTrace("APR-Core/utils/DungeonUtils.lua:18:dungeonKey#1", dungeonKey)--[[/APR_DIAG]]

function APR:IsInsideDungeon(key)
    local data = self.ForeverDungeons[key]
    if not data or not GetInstanceInfo or not IsInInstance then return false end
    local inside, kind = IsInInstance()
    local _, _, _, _, _, _, _, instanceID = GetInstanceInfo()
    return inside and kind == "party" and instanceID == data.instanceID or false
end--[[APR_DIAG]]; APR.IsInsideDungeon = APRTrace("APR-Core/utils/DungeonUtils.lua:24:APR:IsInsideDungeon#2", APR.IsInsideDungeon)--[[/APR_DIAG]]

function APR:IsInDungeonStepContext(step)
    return self:IsInsideDungeon(dungeonKey(step))
end--[[APR_DIAG]]; APR.IsInDungeonStepContext = APRTrace("APR-Core/utils/DungeonUtils.lua:32:APR:IsInDungeonStepContext#3", APR.IsInDungeonStepContext)--[[/APR_DIAG]]

function APR:GetDungeonRun(route, key, create)
    local player = APRData and self.PlayerID and APRData[self.PlayerID]
    if not player then return end
    local runs = player.DungeonRuns
    if not runs and create then runs = {}; player.DungeonRuns = runs end
    local run = runs and runs[route]
    if create and (not run or run.key ~= key) then
        run = { key = key, kills = {}, serial = 1 }
        runs[route] = run
    end
    return run and run.key == key and run or nil
end--[[APR_DIAG]]; APR.GetDungeonRun = APRTrace("APR-Core/utils/DungeonUtils.lua:36:APR:GetDungeonRun#4", APR.GetDungeonRun)--[[/APR_DIAG]]

function APR:ResetDungeonRun(route)
    local player = APRData and self.PlayerID and APRData[self.PlayerID]
    if player and player.DungeonRuns then player.DungeonRuns[route] = nil end
end--[[APR_DIAG]]; APR.ResetDungeonRun = APRTrace("APR-Core/utils/DungeonUtils.lua:49:APR:ResetDungeonRun#5", APR.ResetDungeonRun)--[[/APR_DIAG]]

-- A reload keeps the current run. Leaving and entering again at an entry step
-- starts a new run; Reset route also clears credit, even if progress was already 1.
function APR:ObserveDungeonLocation(step)
    local key = dungeonKey(step)
    if not key or not self.ForeverDungeons[key] or not self.ActiveRoute then return end
    local inside = self:IsInsideDungeon(key)
    local run = self:GetDungeonRun(self.ActiveRoute, key, inside or step.EnterInstance ~= nil)
    if not run then return end
    if inside then
        if step.EnterInstance and run.entered and run.outsideSeen then
            run.kills = {}
            run.serial = (run.serial or 0) + 1
        end
        run.entered, run.outsideSeen = true, nil
    elseif run.entered then
        run.outsideSeen = true
    end
    return run
end--[[APR_DIAG]]; APR.ObserveDungeonLocation = APRTrace("APR-Core/utils/DungeonUtils.lua:56:APR:ObserveDungeonLocation#6", APR.ObserveDungeonLocation)--[[/APR_DIAG]]

function APR:RecordDungeonDeath(guid)
    local step = self:GetCurrentStep()
    local key = dungeonKey(step)
    if not self:IsInsideDungeon(key) or type(guid) ~= "string" then return false end
    local kind, npcID = guid:match("^(%a+)%-[^%-]*%-[^%-]*%-[^%-]*%-[^%-]*%-(%d+)%-")
    if kind ~= "Creature" and kind ~= "Vehicle" then return false end
    npcID = tonumber(npcID)
    local aliases = self.ForeverDungeons[key].bossAliases
    npcID = aliases and aliases[npcID] or npcID
    if not npcID or not self.ForeverDungeons[key].bosses[npcID] then return false end
    local run = self:ObserveDungeonLocation(step)
    if not run then return false end
    run.kills[npcID] = true
    return true
end--[[APR_DIAG]]; APR.RecordDungeonDeath = APRTrace("APR-Core/utils/DungeonUtils.lua:74:APR:RecordDungeonDeath#7", APR.RecordDungeonDeath)--[[/APR_DIAG]]

function APR:GetDungeonKillText(rule)
    return BOSS .. ": " .. (rule.name or tostring(rule.npcID))
end--[[APR_DIAG]]; APR.GetDungeonKillText = APRTrace("APR-Core/utils/DungeonUtils.lua:90:APR:GetDungeonKillText#8", APR.GetDungeonKillText)--[[/APR_DIAG]]

function APR:RenderDungeonKill(step, showDetails)
    local rule = step.KillNPC
    local run = self:ObserveDungeonLocation(step)
    if self:IsInsideDungeon(rule.dungeonKey) and run and run.kills[rule.npcID] then
        self:UpdateNextStep()
        return true
    end
    if showDetails then
        self.currentStep:AddQuestSteps("KillNPC_" .. rule.npcID, self:GetDungeonKillText(rule), "KillNPC", false, true)
        self.currentStep:AddQuestSteps("DungeonKillHelp", L["MANUAL_SKIP"], "KillNPC", false, true)
    end
end--[[APR_DIAG]]; APR.RenderDungeonKill = APRTrace("APR-Core/utils/DungeonUtils.lua:94:APR:RenderDungeonKill#9", APR.RenderDungeonKill)--[[/APR_DIAG]]

function APR:GetDungeonTravelText(step)
    local rule = step.EnterInstance or step.LeaveInstance
    local data = self.ForeverDungeons[rule.dungeonKey]
    local name = data and data.name or UNKNOWN
    if step.EnterInstance then return ENTER_DUNGEON .. ": " .. name end
    return string.format(LEAVE_ZONE, name)
end--[[APR_DIAG]]; APR.GetDungeonTravelText = APRTrace("APR-Core/utils/DungeonUtils.lua:107:APR:GetDungeonTravelText#10", APR.GetDungeonTravelText)--[[/APR_DIAG]]

function APR:RenderDungeonTravel(step)
    local entering = step.EnterInstance ~= nil
    local rule = step.EnterInstance or step.LeaveInstance
    local data = self.ForeverDungeons[rule.dungeonKey]
    if not data then return end
    self:ObserveDungeonLocation(step)
    local inside = self:IsInsideDungeon(rule.dungeonKey)
    local inAnyInstance = IsInInstance and IsInInstance()
    if (entering and inside) or (not entering and not inAnyInstance) then
        self:UpdateNextStep()
        return true
    end
    local label = entering and "EnterInstance" or "LeaveInstance"
    self.currentStep:AddQuestSteps(label, self:GetDungeonTravelText(step), label, false, true)
end--[[APR_DIAG]]; APR.RenderDungeonTravel = APRTrace("APR-Core/utils/DungeonUtils.lua:115:APR:RenderDungeonTravel#11", APR.RenderDungeonTravel)--[[/APR_DIAG]]

-- No target-health polling: an unseen or previously killed boss needs explicit
-- manual completion. Deaths observed elsewhere or in another dungeon never count.
local events = CreateFrame("Frame")
events:RegisterEvent("COMBAT_LOG_EVENT_UNFILTERED")
events:RegisterEvent("ZONE_CHANGED_NEW_AREA")
events:RegisterEvent("PLAYER_ENTERING_WORLD")
events:SetScript("OnEvent", --[[APR_DIAG]]APRTrace("APR-Core/utils/DungeonUtils.lua:137:callback#12", --[[/APR_DIAG]]function(_, event)
    if not APR.ActiveRoute or not APR.settings or not APR.settings.profile.enableAddon then return end
    local step = APR:GetCurrentStep()
    if not dungeonKey(step) then return end
    if event == "COMBAT_LOG_EVENT_UNFILTERED" then
        if not CombatLogGetCurrentEventInfo then return end
        local _, subevent, _, _, _, _, _, destination = CombatLogGetCurrentEventInfo()
        if (subevent == "UNIT_DIED" or subevent == "UNIT_DESTROYED") and APR:RecordDungeonDeath(destination) then
            if step.KillNPC then APR:UpdateStep() end
        end
    else
        APR:ObserveDungeonLocation(step)
        APR:UpdateStep()
    end
end--[[APR_DIAG]])--[[/APR_DIAG]])
